def visit_middleware_tree_item(self, mti: MiddlewareTreeItemInfo) -> str:
    """Visit a MiddlewareTreeItemInfo instance. Usually called by `process`."""
    symbol = mti._symbols.get(mti.name, '→')
    return '{0}{1} {2.class_name}.{2.name}'.format(self.tab, symbol, mti)

def visit_middleware_tree(self, m_tree: MiddlewareTreeInfo) -> str:
    """Visit a MiddlewareTreeInfo instance. Usually called by `process`."""
    before = len(m_tree.request) + len(m_tree.resource)
    after = len(m_tree.response)

    if before + after == 0:
        return ''

    each = 2
    initial = self.indent
    if after > before:
        self.indent += each * (after - before)

    text = []
    for r in m_tree.request:
        text.append(self.process(r))
        self.indent += each
    if text:
        text.append('')
    for r in m_tree.resource:
        text.append(self.process(r))
        self.indent += each

    if m_tree.resource or not text:
        text.append('')
    self.indent += each
    text.append('{}├── Process route responder'.format(self.tab))
    self.indent -= each
    if m_tree.response:
        text.append('')

    for r in m_tree.response:
        self.indent -= each
        text.append(self.process(r))

    self.indent = initial
    return '\n'.join(text)

def visit_middleware(self, middleware: MiddlewareInfo) -> str:
    """Visit a MiddlewareInfo instance. Usually called by `process`."""
    text = self.process(middleware.middleware_tree)
    if self.verbose:
        self.indent += 4
        m_text = '\n'.join(self.process(m) for m in middleware.middleware_classes)
        self.indent -= 4
        if m_text:
            text += '\n{}- Middleware classes:\n{}'.format(self.tab, m_text)

    return text

def _filter_internal(iterable, return_internal):
    """Filter the internal elements of an iterable."""
    if return_internal:
        return iterable
    return [el for el in iterable if not el.internal]

def wrapper():
    try:
        for item in iterable:
            yield item
    finally:
        if hasattr(iterable, 'close'):
            iterable.close()

def _before(responder_or_resource):
    if isinstance(responder_or_resource, type):
        resource = responder_or_resource

        for responder_name, responder in getmembers(resource, callable):
            if _DECORABLE_METHOD_NAME.match(responder_name):
                # This pattern is necessary to capture the current value of
                # responder in the do_before_all closure; otherwise, they
                # will capture the same responder variable that is shared
                # between iterations of the for loop, above.
                def let(responder=responder):
                    do_before_all = _wrap_with_before(
                        responder, action, args, kwargs, is_async
                    )

                    setattr(resource, responder_name, do_before_all)

                let()

        return resource

    else:
        responder = responder_or_resource
        do_before_one = _wrap_with_before(responder, action, args, kwargs, is_async)

        return do_before_one

def let(responder=responder):
    do_before_all = _wrap_with_before(
        responder, action, args, kwargs, is_async
    )

    setattr(resource, responder_name, do_before_all)

def _after(responder_or_resource):
    if isinstance(responder_or_resource, type):
        resource = responder_or_resource

        for responder_name, responder in getmembers(resource, callable):
            if _DECORABLE_METHOD_NAME.match(responder_name):

                def let(responder=responder):
                    do_after_all = _wrap_with_after(
                        responder, action, args, kwargs, is_async
                    )

                    setattr(resource, responder_name, do_after_all)

                let()

        return resource

    else:
        responder = responder_or_resource
        do_after_one = _wrap_with_after(responder, action, args, kwargs, is_async)

        return do_after_one

def let(responder=responder):
    do_after_all = _wrap_with_after(
        responder, action, args, kwargs, is_async
    )

    setattr(resource, responder_name, do_after_all)

def do_after(self, req, resp, *args, **kwargs):
    if args:
        _merge_responder_args(args, kwargs, extra_argnames)

    responder(self, req, resp, **kwargs)
    action(req, resp, self, *action_args, **action_kwargs)

def do_before(self, req, resp, *args, **kwargs):
    if args:
        _merge_responder_args(args, kwargs, extra_argnames)

    action(req, resp, self, kwargs, *action_args, **action_kwargs)
    responder(self, req, resp, **kwargs)

def filename(self):
    if self._filename is None:

        if self._content_disposition is None:
            value = self._headers.get(b'content-disposition', b'')
            self._content_disposition = cgi.parse_header(value.decode())

        _, params = self._content_disposition

        # NOTE(vytas): Supporting filename* as per RFC 5987, as that has
        #   been spotted in the wild, even though RFC 7578 forbids it.
        match = _FILENAME_STAR_RFC5987.match(params.get('filename*', ''))
        if match:
            charset, value = match.groups()
            try:
                self._filename = unquote_to_bytes(value).decode(charset)
            except (ValueError, LookupError) as err:
                raise MultipartParseError(
                    description='invalid text or charset: {}'.format(charset)
                ) from err
        else:
            value = params.get('filename')
            if value is None:
                return None
            self._filename = value

    return self._filename

