def range(self):
    value = self.get_header('Range')
    if value is None:
        return None

    if '=' in value:
        unit, sep, req_range = value.partition('=')
    else:
        msg = "The value must be prefixed with a range unit, e.g. 'bytes='"
        raise errors.HTTPInvalidHeader(msg, 'Range')

    if ',' in req_range:
        msg = 'The value must be a continuous range.'
        raise errors.HTTPInvalidHeader(msg, 'Range')

    try:
        first, sep, last = req_range.partition('-')

        if not sep:
            raise ValueError()

        if first and last:
            first, last = (int(first), int(last))
            if last < first:
                raise ValueError()
        elif first:
            first, last = (int(first), -1)
        elif last:
            first, last = (-int(last), -1)
            if first >= 0:
                raise ValueError()
        else:
            msg = 'The range offsets are missing.'
            raise errors.HTTPInvalidHeader(msg, 'Range')

        return first, last

    except ValueError:
        href = 'https://tools.ietf.org/html/rfc7233'
        href_text = 'HTTP/1.1 Range Requests'
        msg = 'It must be a range formatted according to RFC 7233.'
        raise errors.HTTPInvalidHeader(msg, 'Range', href=href, href_text=href_text)

def range_unit(self):
    value = self.get_header('Range')
    if value is None:
        return None

    if value and '=' in value:
        unit, sep, req_range = value.partition('=')
        return unit
    else:
        msg = "The value must be prefixed with a range unit, e.g. 'bytes='"
        raise errors.HTTPInvalidHeader(msg, 'Range')

def headers(self):
    # NOTE(kgriffs: First time here will cache the dict so all we
    # have to do is clone it in the future.
    if self._cached_headers is None:
        headers = self._cached_headers = {}

        env = self.env
        for name, value in env.items():
            if name.startswith('HTTP_'):
                # NOTE(kgriffs): Don't take the time to fix the case
                # since headers are supposed to be case-insensitive
                # anyway.
                headers[name[5:].replace('_', '-')] = value

            elif name in WSGI_CONTENT_HEADERS:
                headers[name.replace('_', '-')] = value

    return self._cached_headers

def cookies(self):
    if self._cookies_collapsed is None:
        if self._cookies is None:
            header_value = self.get_header('Cookie')
            if header_value:
                self._cookies = helpers.parse_cookie_header(header_value)
            else:
                self._cookies = {}

        self._cookies_collapsed = {n: v[0] for n, v in self._cookies.items()}

    return self._cookies_collapsed

def __iter__(self):
    prologue = True
    delimiter = self._dash_boundary
    stream = self._stream
    max_headers_size = self._parse_options.max_body_part_headers_size
    remaining_parts = self._parse_options.max_body_part_count

    while True:
        # NOTE(vytas): Either exhaust the unused stream part, or skip
        #   the prologue.
        try:
            stream.pipe_until(delimiter, consume_delimiter=True)

            if prologue:
                # NOTE(vytas): RFC 7578, section 4.1.
                #   As with other multipart types, the parts are delimited
                #   with a boundary delimiter, constructed using CRLF,
                #   "--", and the value of the "boundary" parameter.
                delimiter = _CRLF + delimiter
                prologue = False

            separator = stream.read_until(_CRLF, 2, consume_delimiter=True)
            if separator == b'--':
                # NOTE(vytas): boundary delimiter + '--\r\n' signals the
                # end of a multipart form.
                break
            elif separator:
                raise MultipartParseError(description='unexpected form structure')

        except errors.DelimiterError as err:
            raise MultipartParseError(
                description='unexpected form structure'
            ) from err

        headers = {}
        try:
            headers_block = stream.read_until(
                _CRLF_CRLF, max_headers_size, consume_delimiter=True
            )
        except errors.DelimiterError as err:
            raise MultipartParseError(
                description='incomplete body part headers'
            ) from err

        for line in headers_block.split(_CRLF):
            name, sep, value = line.partition(b': ')
            if sep:
                name = name.lower()

                # NOTE(vytas): RFC 7578, section 4.5.
                #   This use is deprecated for use in contexts that support
                #   binary data such as HTTP. Senders SHOULD NOT generate
                #   any parts with a Content-Transfer-Encoding header
                #   field.
                #
                #   Currently, no deployed implementations that send such
                #   bodies have been discovered.
                if name == b'content-transfer-encoding' and value != b'binary':
                    raise MultipartParseError(
                        description=(
                            'the deprecated Content-Transfer-Encoding '
                            'header field is unsupported'
                        )
                    )
                # NOTE(vytas): RFC 7578, section 4.8.
                #   Other header fields MUST NOT be included and MUST be
                #   ignored.
                elif name in _ALLOWED_CONTENT_HEADERS:
                    headers[name] = value

        remaining_parts -= 1
        if remaining_parts < 0 < self._parse_options.max_body_part_count:
            raise MultipartParseError(
                description='maximum number of form body parts exceeded'
            )

        yield BodyPart(stream.delimit(delimiter), headers, self._parse_options)

def get_encoding_from_headers(headers):
    """Return encoding from given HTTP Header Dict.

    Args:
        headers(dict): Dictionary from which to extract encoding. Header
            names must either be lowercase or the dict must support
            case-insensitive lookups.
    """

    content_type = headers.get('content-type')

    if not content_type:
        return None

    content_type, params = cgi.parse_header(content_type)

    if 'charset' in params:
        return params['charset'].strip('\'"')

    # NOTE(kgriffs): Added checks for text/event-stream and application/json
    if content_type in ('text/event-stream', 'application/json'):
        return 'UTF-8'

    if 'text' in content_type:
        return 'ISO-8859-1'

    return None

