def content_type(self):
    # NOTE(vytas): RFC 7578, section 4.4.
    #   Each part MAY have an (optional) "Content-Type" header field, which
    #   defaults to "text/plain".
    value = self._headers.get(b'content-type', b'text/plain')
    return value.decode('ascii')

def is_ascii_encodable(s):
    """Check if argument encodes to ascii without error."""
    try:
        s.encode('ascii')
    except UnicodeEncodeError:
        # NOTE(tbug): Py3 will raise this if string contained
        # chars that could not be ascii encoded
        return False
    except AttributeError:
        # NOTE(tbug): s is probably not a string type
        return False
    return True

def __init__(self, status, headers):
    self._status = status
    self._status_code = int(status[:3])
    self._headers = CaseInsensitiveDict(headers)

    cookies = http_cookies.SimpleCookie()
    for name, value in headers:
        if name.lower() == 'set-cookie':
            cookies.load(value)

    self._cookies = dict(
        (morsel.key, Cookie(morsel)) for morsel in cookies.values()
    )

    self._encoding = helpers.get_encoding_from_headers(self._headers)

