    except errors.HTTPInvalidHeader:  # pragma: no cover
        # NOTE(kgriffs): The content-length header was specified,
        # but it had an invalid value. Assume no content.
        content_length = 0

    return BoundedStream(self.env['wsgi.input'], content_length)

