def _translate_webserver_error(self, ex):
    s = str(ex)

    # NOTE(kgriffs): uvicorn or any other server using the "websockets"
    #   package that allows exceptions to bubble up
    if 'code = 1000 (OK)' in s:
        return errors.WebSocketDisconnected(WSCloseCode.NORMAL)

    # NOTE(kgriffs): Autobahn (used by Daphne) raises a generic exception
    #   with this message
    if 'protocol accepted must be from the list' in s:
        return ValueError(
            'WebSocket subprotocol must be from the list sent by the client'
        )

    return None

async def stop(self):
    if not self._pump_task:
        return

    self._pump_task.cancel()
    try:
        await self._pump_task
    except asyncio.CancelledError:
        pass

    self._pump_task = None

async def _ws_cleanup_on_error(self, ws):
    # NOTE(kgriffs): Attempt to close cleanly on our end
    try:
        await ws.close(self.ws_options.error_close_code)
    except Exception as ex:
        # NOTE(kgriffs): This can be raised by Daphne. We also
        #   may raise it ourselves for errors codes < 1000, but in that
        #   case we just include this string in the exception message
        #   to make it easier to verify test coverage of the following.
        if 'invalid close code' in str(ex).lower():
            await ws.close(_FALLBACK_WS_ERROR_CODE)
        else:
            falcon._logger.warning(
                (
                    '[FALCON] Attempt to close web connection cleanly '
                    'failed due to raised error.'
                ),
                exc_info=True,
            )
            raise

def _require_accepted(self):
    if self._state == _WebSocketState.HANDSHAKE:
        raise errors.OperationNotAllowed(
            'WebSocket connection has not yet been accepted'
        )
    elif self._state == _WebSocketState.CLOSED:
        raise errors.WebSocketDisconnected(self._close_code)

def headers(self):
    # NOTE(kgriffs: First time here will cache the dict so all we
    # have to do is clone it in the future.
    if self._cached_headers is None:
        self._cached_headers = {
            name.decode('latin1'): value.decode('latin1')
            for name, value in self._asgi_headers.items()
        }

    return self._cached_headers

def stream(self):
    if self.is_websocket:
        raise errors.UnsupportedError(
            'ASGI does not support reading the WebSocket handshake request body.'
        )

    if not self._stream:
        self._stream = BoundedStream(
            self._receive,
            first_event=self._first_event,
            content_length=self.content_length,
        )

    return self._stream

def scheme(self):
    # PERF(kgriffs): Use try...except because we normally expect the
    #   key to be present.
    try:
        return self.scope['scheme']
    except KeyError:
        pass

    return 'ws' if self.is_websocket else 'http'

def forwarded_scheme(self):
    # PERF(kgriffs): Since the Forwarded header is still relatively
    # new, we expect X-Forwarded-Proto to be more common, so
    # try to avoid calling self.forwarded if we can, since it uses a
    # try...catch that will usually result in a relatively expensive
    # raised exception.
    if b'forwarded' in self._asgi_headers:
        forwarded = self.forwarded
        if forwarded:
            # Use first hop, fall back on own scheme
            scheme = forwarded[0].scheme or self.scheme
        else:
            scheme = self.scheme
    else:
        # PERF(kgriffs): This call should normally succeed, so
        # just go for it without wasting time checking it
        # first. Note also that the indexing operator is
        # slightly faster than using get().
        try:
            scheme = (
                self._asgi_headers[b'x-forwarded-proto'].decode('latin1').lower()
            )
        except KeyError:
            scheme = self.scheme

    return scheme

def forwarded_host(self):
    # PERF(kgriffs): Since the Forwarded header is still relatively
    # new, we expect X-Forwarded-Host to be more common, so
    # try to avoid calling self.forwarded if we can, since it uses a
    # try...catch that will usually result in a relatively expensive
    # raised exception.
    if b'forwarded' in self._asgi_headers:
        forwarded = self.forwarded
        if forwarded:
            # Use first hop, fall back on self
            host = forwarded[0].host or self.netloc
        else:
            host = self.netloc
    else:
        # PERF(kgriffs): This call should normally succeed, assuming
        # that the caller is expecting a forwarded header, so
        # just go for it without wasting time checking it
        # first.
        try:
            host = self._asgi_headers[b'x-forwarded-host'].decode('latin1')
        except KeyError:
            host = self.netloc

    return host

def access_route(self):
    if self._cached_access_route is None:
        # PERF(kgriffs): 'client' is optional according to the ASGI spec
        #   but it will probably be present, hence the try...except.
        try:
            # NOTE(kgriffs): The ASGI spec states that this can be
            #   any iterable. So we need to read and cache it in
            #   case the iterable is forward-only. But that is
            #   effectively what we are doing since we only ever
            #   access this field when setting self._cached_access_route
            client, __ = self.scope['client']
        except KeyError:
            # NOTE(kgriffs): Default to localhost so that app logic does
            #   note have to special-case the handling of a missing
            #   client field in the connection scope. This should be
            #   a reasonable default, but we can change it later if
            #   that turns out not to be the case.
            client = '127.0.0.1'

        headers = self._asgi_headers

        if b'forwarded' in headers:
            self._cached_access_route = []
            for hop in self.forwarded:
                if hop.src is not None:
                    host, __ = parse_host(hop.src)
                    self._cached_access_route.append(host)
        elif b'x-forwarded-for' in headers:
            addresses = headers[b'x-forwarded-for'].decode('latin1').split(',')
            self._cached_access_route = [ip.strip() for ip in addresses]
        elif b'x-real-ip' in headers:
            self._cached_access_route = [headers[b'x-real-ip'].decode('latin1')]

        if self._cached_access_route:
            if self._cached_access_route[-1] != client:
                self._cached_access_route.append(client)
        else:
            self._cached_access_route = [client] if client else []

    return self._cached_access_route

def remote_addr(self):
    route = self.access_route
    return route[-1]

def if_none_match(self):
    if self._cached_if_none_match is None:
        header_value = self._asgi_headers.get(b'if-none-match')
        if header_value:
            self._cached_if_none_match = helpers._parse_etags(
                header_value.decode('latin1')
            )

    return self._cached_if_none_match

def _validate_asgi_scope(scope_type, spec_version, http_version):
    if scope_type == 'http':
        spec_version = spec_version or '2.0'
        if not spec_version.startswith('2.'):
            raise UnsupportedScopeError(
                f'The ASGI "http" scope version {spec_version} is not supported.'
            )
        if http_version not in {'1.0', '1.1', '2', '3'}:
            raise UnsupportedError(
                f'The ASGI "http" scope does not support HTTP version {http_version}.'
            )
        return spec_version

    if scope_type == 'websocket':
        spec_version = spec_version or '2.0'
        if not spec_version.startswith('2.'):
            raise UnsupportedScopeError(
                'Only versions 2.x of the ASGI "websocket" scope are supported.'
            )
        if http_version not in {'1.1', '2', '3'}:
            raise UnsupportedError(
                'The ASGI "websocket" scope does not support '
                f'HTTP version {http_version}.'
            )
        return spec_version

    if scope_type == 'lifespan':
        spec_version = spec_version or '1.0'
        if not spec_version.startswith('1.') and not spec_version.startswith('2.'):
            raise UnsupportedScopeError(
                'Only versions 1.x and 2.x of the ASGI "lifespan" scope are supported.'
            )
        return spec_version

    # NOTE(kgriffs): According to the ASGI spec: "Applications should
    #   actively reject any protocol that they do not understand with
    #   an Exception (of any type)."
    raise UnsupportedScopeError(f'The ASGI "{scope_type}" scope type is not supported.')

def _schedule_callbacks(self, resp):
    callbacks = resp._registered_callbacks
    # PERF(vytas): resp._registered_callbacks is already checked directly
    # to shave off a function call since this is a hot/critical code path.
    # if not callbacks:
    #     return

    loop = get_running_loop()

    for cb, is_async in callbacks:
        if is_async:
            loop.create_task(cb())
        else:
            loop.run_in_executor(None, cb)

async def _call_lifespan_handlers(self, ver, scope, receive, send):
    while True:
        event = await receive()
        if event['type'] == 'lifespan.startup':
            # PERF(vytas): Perform these sanity checks upon application
            #   startup, as opposed to repeating them every request.

            # NOTE(vytas): If missing, 'asgi' is populated in __call__.
            asgi_info = scope['asgi']
            version = asgi_info.get('version', '2.0 (implicit)')
            if not version.startswith('3.'):
                await send(
                    {
                        'type': EventType.LIFESPAN_STARTUP_FAILED,
                        'message': (
                            'Falcon requires ASGI version 3.x. '
                            f'Detected: {version}.'
                        ),
                    }
                )
                return

            if self.req_options.auto_parse_form_urlencoded:
                await send(
                    {
                        'type': EventType.LIFESPAN_STARTUP_FAILED,
                        'message': (
                            'The deprecated WSGI RequestOptions.'
                            'auto_parse_form_urlencoded '
                            'option is not supported for Falcon ASGI apps. '
                            'Please use Request.get_media() instead. '
                        ),
                    }
                )
                return

            for handler in self._unprepared_middleware:
                if hasattr(handler, 'process_startup'):
                    try:
                        await handler.process_startup(scope, event)
                    except Exception:
                        await send(
                            {
                                'type': EventType.LIFESPAN_STARTUP_FAILED,
                                'message': traceback.format_exc(),
                            }
                        )
                        return

            await send({'type': EventType.LIFESPAN_STARTUP_COMPLETE})

        elif event['type'] == 'lifespan.shutdown':
            for handler in reversed(self._unprepared_middleware):
                if hasattr(handler, 'process_shutdown'):
                    try:
                        await handler.process_shutdown(scope, event)
                    except Exception:
                        await send(
                            {
                                'type': EventType.LIFESPAN_SHUTDOWN_FAILED,
                                'message': traceback.format_exc(),
                            }
                        )
                        return

            await send({'type': EventType.LIFESPAN_SHUTDOWN_COMPLETE})
            return

async def watch_disconnect():
    while True:
        received_event = await receive()
        if received_event['type'] == EventType.HTTP_DISCONNECT:
            break

def __aiter__(self):
    # NOTE(kgriffs): This returns an async generator, but that's OK because
    #   it also implements the iterator protocol defined in PEP 492, albeit
    #   in a more efficient way than a regular async iterator.
    return self._iter_content()

async def _iter_content(self):
    if self._closed:
        raise OperationNotAllowed(
            'This stream is closed; no further operations on it are permitted.'
        )

    if self.eof:
        return

    if self._iteration_started:
        raise OperationNotAllowed('This stream is already being iterated over.')

    self._iteration_started = True

    if self._buffer:
        next_chunk = self._buffer
        self._buffer = b''

        self._pos += len(next_chunk)
        yield next_chunk

    while self._bytes_remaining > 0:
        event = await self._receive()

        # PERF(kgriffs): Use try...except because we normally expect the
        #   'body' key to be present.
        try:
            next_chunk = event['body']
        except KeyError:
            pass
        else:
            # NOTE(kgriffs): No need to yield empty body chunks.
            if next_chunk:
                next_chunk_len = len(next_chunk)

                if next_chunk_len <= self._bytes_remaining:
                    self._bytes_remaining -= next_chunk_len
                    self._pos += next_chunk_len
                else:
                    # NOTE(kgriffs): We received more data than expected,
                    #   so truncate to the expected length.
                    next_chunk = next_chunk[: self._bytes_remaining]
                    self._pos += self._bytes_remaining
                    self._bytes_remaining = 0

                yield next_chunk

        # NOTE(kgriffs): Per the ASGI spec, more_body is optional
        #   and should be considered False if not present.
        # NOTE(kgriffs): This also handles the case of receiving
        #   the event: {'type': 'http.disconnect'}
        # PERF(kgriffs): event.get() is more elegant, but uses a
        #   few more CPU cycles.
        if not ('more_body' in event and event['more_body']):
            self._bytes_remaining = 0

def fileno(self):
    """Raise an instance of OSError since a file descriptor is not used."""
    raise OSError('This IO object does not use a file descriptor')

def fileno(self):
    """Raise an instance of OSError since a file descriptor is not used."""
