    return json_module.loads(self.text)

async def __aenter__(self):
    lifespan_scope = {
        'type': ScopeType.LIFESPAN,
        'asgi': {
            'version': '3.0',
            'spec_version': '2.0',
        },
    }

    lifespan_event_emitter = helpers.ASGILifespanEventEmitter(self._shutting_down)

    # NOTE(kgriffs): We assume this is a Falcon ASGI app, which supports
    #   the lifespan protocol and thus we do not need to catch
    #   exceptions that would signify no lifespan protocol support.
    self._lifespan_task = get_running_loop().create_task(
        self.app(
            lifespan_scope, lifespan_event_emitter, self._lifespan_event_collector
        )
    )

    await _wait_for_startup(self._lifespan_event_collector.events)

    return self

async def _wait_for_startup(events):
    # NOTE(kgriffs): This is covered, but our gate for some reason doesn't
    #   understand `while True`.
    while True:  # pragma: nocover
        for e in events:
            if e['type'] == 'lifespan.startup.failed':
                raise RuntimeError(
                    'ASGI app returned lifespan.startup.failed. ' + e['message']
                )

        if any(e['type'] == 'lifespan.startup.complete' for e in events):
            break

        # NOTE(kgriffs): Yield to the concurrent lifespan task
        await asyncio.sleep(0)

async def _wait_for_shutdown(events):
    # NOTE(kgriffs): This is covered, but our gate for some reason doesn't
    #   understand `while True`.
    while True:  # pragma: nocover
        for e in events:
            if e['type'] == 'lifespan.shutdown.failed':
                raise RuntimeError(
                    'ASGI app returned lifespan.shutdown.failed. ' + e['message']
                )

        if any(e['type'] == 'lifespan.shutdown.complete' for e in events):
            break

        # NOTE(kgriffs): Yield to the concurrent lifespan task
        await asyncio.sleep(0)

def deprecated_args(*, allowed_positional, is_method=True):
    """Flag a method call with positional args as deprecated.

    Keyword Args:
        allowed_positional (int): Number of allowed positional arguments
        is_method (bool, optional): The decorated function is a method. Will
          add one to the number of allowed positional args to account for
          ``self``. Defaults to True.
    """

    template = (
        'Calls to {{fn}}(...) with{arg_text} positional args are deprecated.'
        ' Please specify them as keyword arguments instead.'
    )
    text = ' more than {}'.format(allowed_positional) if allowed_positional else ''
    warn_text = template.format(arg_text=text)
    if is_method:
        allowed_positional += 1

    def deprecated_args(fn):
        @functools.wraps(fn)
        def wraps(*args, **kwargs):
            if len(args) > allowed_positional:
                warnings.warn(
                    warn_text.format(fn=fn.__qualname__),
                    DeprecatedWarning,
                    stacklevel=2,
                )
            return fn(*args, **kwargs)

        return wraps

    return deprecated_args

def decorator(func):

    object_name = 'property' if is_property else 'function'
    post_name = '' if is_property else '(...)'
    message = 'Call to deprecated {} {}{}. {}'.format(
        object_name, method_name or func.__name__, post_name, instructions
    )

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        warnings.warn(message, category=DeprecatedWarning, stacklevel=2)

        return func(*args, **kwargs)

    return wrapper

def wrapper(*args, **kwargs):
    warnings.warn(message, category=DeprecatedWarning, stacklevel=2)

    return func(*args, **kwargs)

def deprecated_args(fn):
    @functools.wraps(fn)
    def wraps(*args, **kwargs):
        if len(args) > allowed_positional:
            warnings.warn(
                warn_text.format(fn=fn.__qualname__),
                DeprecatedWarning,
                stacklevel=2,
            )
        return fn(*args, **kwargs)

    return wraps

def wraps(*args, **kwargs):
    if len(args) > allowed_positional:
        warnings.warn(
            warn_text.format(fn=fn.__qualname__),
            DeprecatedWarning,
            stacklevel=2,
        )
    return fn(*args, **kwargs)

def _create_char_encoder(allowed_chars):

    lookup = {}

    for code_point in range(256):
        if chr(code_point) in allowed_chars:
            encoded_char = chr(code_point)
        else:
            encoded_char = '%{0:02X}'.format(code_point)

        lookup[code_point] = encoded_char

    return lookup.__getitem__

def _filter_blank(i):
