    return False

def to_xml(self):
    """Return an XML-encoded representation of the error.

    Returns:
        bytes: An XML document for the error.

    """

    error_element = et.Element('error')

    et.SubElement(error_element, 'title').text = self.title

    if self.description is not None:
        et.SubElement(error_element, 'description').text = self.description

    if self.code is not None:
        et.SubElement(error_element, 'code').text = str(self.code)

    if self.link is not None:
        link_element = et.SubElement(error_element, 'link')

        for key in ('text', 'href', 'rel'):
            et.SubElement(link_element, key).text = self.link[key]

    return b'<?xml version="1.0" encoding="UTF-8"?>' + et.tostring(
        error_element, encoding='utf-8'
    )

def serialize(self, handler=None):
    """Serialize this event to string.

    Args:
        handler: Handler object that will be used to serialize the ``json``
            attribute to string. When not provided, a default handler using
            the builtin JSON library will be used (default ``None``).

    Returns:
        bytes: string representation of this event.
    """
    if self.comment is not None:
        block = f': {self.comment}\n'
    else:
        block = ''

    if self.event is not None:
        block += f'event: {self.event}\n'

    if self.event_id is not None:
        # NOTE(kgriffs): f-strings are a tiny bit faster than str().
        block += f'id: {self.event_id}\n'

    if self.retry is not None:
        block += f'retry: {self.retry}\n'

    if self.data is not None:
        # NOTE(kgriffs): While this decode() may seem unnecessary, it
        #   does provide a check to ensure it is valid UTF-8. I'm also
        #   assuming for the moment that most people will not use this
        #   attribute, but rather the text and json ones instead. If that
        #   is true, it makes sense to construct the entire string
        #   first, then encode it all in one go at the end.
        block += f'data: {self.data.decode()}\n'
    elif self.text is not None:
        block += f'data: {self.text}\n'
    elif self.json is not None:
        if handler is None:
            handler = _DEFAULT_JSON_HANDLER
        serialized = handler.serialize(self.json, MEDIA_JSON)
        block += 'data: '
        return block.encode() + serialized + b'\n\n'

    if not block:
        return b': ping\n\n'

    return (block + '\n').encode()

def __init__(self, num_digits=None, min=None, max=None):
    if num_digits is not None and num_digits < 1:
        raise ValueError('num_digits must be at least 1')

    self._num_digits = num_digits
    self._min = min
    self._max = max

def __init__(self, body, headers):
    self._body = body
    self._headers = headers

def match(self, path):
    """Check whether the given path matches this route."""
    if self._fallback_filename is None:
        return path.startswith(self._prefix)
    return path.startswith(self._prefix) or path == self._prefix[:-1]

def __next__(self):
    data = self._stream.read(self._block_size)

    if data == b'':
        raise StopIteration
    else:
        return data

async def pipe_until(self, delimiter, destination=None, consume_delimiter=False):
    async for chunk in self._iter_delimited(delimiter):
        if destination is not None:
            await destination.write(chunk)

    if consume_delimiter:
        await self._consume_delimiter(delimiter)

def close(self):
    try:
        self._stream.close()
    except (AttributeError, TypeError):
        pass

def convert(self, value):
    if self._num_digits is not None and len(value) != self._num_digits:
        return None

    # NOTE(kgriffs): int() will accept numbers with preceding or
    # trailing whitespace, so we need to do our own check. Using
    # strip() is faster than either a regex or a series of or'd
    # membership checks via "in", esp. as the length of contiguous
    # numbers in the value grows.
    if value.strip() != value:
        return None

    try:
        value = int(value)
    except ValueError:
        return None

    if self._min is not None and value < self._min:
        return None

    if self._max is not None and value > self._max:
        return None

    return value

def convert(self, value):
    try:
        return strptime(value, self._format_string)
    except ValueError:
        return None

def convert(self, value):
    try:
        return uuid.UUID(value)
    except ValueError:
        return None

def read(self, size=-1):
    """Read the underlying file object, within the specified bounds."""
    if size < 0:
        size = self.remaining
    else:
        size = min(size, self.remaining)
    data = self.fh.read(size)
    self.remaining -= len(data)
    return data

def _fill_buffer(self):
    # PERF(vytas): In Cython, bind types:
    #   cdef Py_ssize_t read_size

    if self._buffer_len - self._buffer_pos < self._chunk_size:
        read_size = self._chunk_size - (self._buffer_len - self._buffer_pos)

        if self._buffer_pos == 0:
            self._buffer += self._perform_read(read_size)
        else:
            self._buffer = self._buffer[self._buffer_pos :] + self._perform_read(
                read_size
            )
            self._buffer_pos = 0

        self._buffer_len = len(self._buffer)

def peek(self, size=-1):
    if size < 0 or size > self._chunk_size:
        size = self._chunk_size

    if self._buffer_len - self._buffer_pos < size:
        self._fill_buffer()

    return self._buffer[self._buffer_pos : self._buffer_pos + size]

def read_until(self, delimiter, size=-1, consume_delimiter=False):
    # PERF(vytas): In Cython, bind types:
    #   cdef Py_ssize_t read_size
    #   cdef result

    read_size = self._normalize_size(size)
    if read_size <= self._max_join_size:
        return self._read_until(delimiter, read_size, consume_delimiter)

    # NOTE(vytas): A large size was requested, optimize for memory
    #   consumption by avoiding to momentarily keep both the chunks and the
    #   joint result in memory at the same time.
    result = io.BytesIO()
    self.pipe_until(delimiter, result, consume_delimiter, read_size)
    return result.getvalue()

def delimit(self, delimiter):
    read = functools.partial(self.read_until, delimiter)
    return type(self)(read, self._normalize_size(None), self._chunk_size)

def readline(self, size=-1):
    size = self._normalize_size(size)

    result = self.read_until(b'\n', size)
    if len(result) < size:
        return result + self.read(1)
    return result

def readlines(self, hint=-1):
    # PERF(vytas): In Cython, bind types:
    #   cdef Py_ssize_t read
    #   cdef list result = []
    read = 0
    result = []

    while True:
        line = self.readline()
        if not line:
            break
        result.append(line)

        if hint >= 0:
            read += len(line)
            if read >= hint:
                break

    return result

def find_by_media_type(self, media_type, default, raise_not_found=True):
    # PERF(jmvrbanac): Check via a quick methods first for performance
    if media_type == '*/*' or not media_type:
        media_type = default

    try:
        return self.data[media_type]
    except KeyError:
        pass

    # PERF(jmvrbanac): Fallback to the slower method.
    # NOTE(kgriffs): Wrap keys in a tuple to make them hashable.
    resolved = _best_match(media_type, tuple(self.data.keys()))

    if not resolved:
        if raise_not_found:
            raise errors.HTTPUnsupportedMediaType(
                description='{0} is an unsupported media type.'.format(media_type)
            )
        return None

    return self.data[resolved]

def _best_match(media_type, all_media_types):
    result = None

    try:
        # NOTE(jmvrbanac): Mimeparse will return an empty string if it can
        # parse the media type, but cannot find a suitable type.
        result = mimeparse.best_match(all_media_types, media_type)
    except ValueError:
        pass

    return result

def resolve(media_type, default, raise_not_found=True):
    if media_type == '*/*' or not media_type:
        media_type = default

    # PERF(kgriffs): Under CPython we do not need this shortcut to
    #   improve performance since most calls will be resolved by the
    #   LRU cache on resolve(). On the other hand, it doesn't hurt,
    #   and it certainly makes a difference under PyPy.
    try:
        handler = self.data[media_type]
    except KeyError:
        handler = None

    if not handler:
        # PERF(kgriffs): We just do this slower check every time, rather
        #   than trying to first check the dict directly, since the result
        #   will almost always be cached anyway.
        # NOTE(kgriffs): Wrap keys in a tuple to make them hashable.
        matched_type = _best_match(media_type, tuple(self.data.keys()))

        if not matched_type:
            if raise_not_found:
                raise errors.HTTPUnsupportedMediaType(
                    description='{0} is an unsupported media type.'.format(
                        media_type
                    )
                )

            return None, None, None

        handler = self.data[matched_type]

    return (
        handler,
        getattr(handler, '_serialize_sync', None),
        getattr(handler, '_deserialize_sync', None),
    )

def index(self):
    response.headers.update(_headers)
    return _body

async def get_media(self):
    if self._media is None:
        handler, _, _ = self._parse_options.media_handlers._resolve(
            self.content_type, 'text/plain'
        )

        try:
            self._media = await handler.deserialize_async(
                self.stream, self.content_type, None
            )
        finally:
            if handler.exhaust_stream:
                await self.stream.exhaust()

    return self._media

async def get_text(self):
    content_type, options = cgi.parse_header(self.content_type)
    if content_type != 'text/plain':
        return None

    charset = options.get('charset', self._parse_options.default_charset)
    try:
        return (await self.get_data()).decode(charset)
    except (ValueError, LookupError) as err:
        raise MultipartParseError(
            description='invalid text or charset: {}'.format(charset)
        ) from err

def _prepend_buffer(self, chunk):
    if self._buffer_len > self._buffer_pos:
        self._buffer = chunk + self._buffer[self._buffer_pos :]
        self._buffer_len = len(self._buffer)
    else:
        self._buffer = chunk
        self._buffer_len = len(chunk)

    self._buffer_pos = 0

def __aiter__(self):
    if self._iteration_started:
        raise OperationNotAllowed('This stream is already being iterated over.')

    self._iteration_started = True

    # PERF(vytas): Do not wrap unless needed.
    if self._buffer_len > self._buffer_pos:
        return self._iter_with_buffer()
    return self._source

def tell(self):
    """Return the number of bytes read from the stream so far."""
    return self._consumed - (self._buffer_len - self._buffer_pos)

def _deserialize(self, data):
    if not data:
        raise errors.MediaNotFoundError('MessagePack')
    try:
        # NOTE(jmvrbanac): Using unpackb since we would need to manage
        # a buffer for Unpacker() which wouldn't gain us much.
        return self._unpackb(data, raw=False)
    except ValueError as err:
        raise errors.MediaMalformedError('MessagePack') from err

def deserialize(self, payload: bytes) -> object:
    # NOTE(jmvrbanac): Using unpackb since we would need to manage
    #   a buffer for Unpacker() which wouldn't gain us much.
    return self._unpackb(payload, raw=False)

def serialize(self, media, content_type=None) -> bytes:
    # NOTE(vytas): Setting doseq to True to mirror the parse_query_string
    # behaviour.
    return urlencode(media, doseq=True).encode()

def _deserialize(self, body):
    try:
        # NOTE(kgriffs): According to http://goo.gl/6rlcux the
        # body should be US-ASCII. Enforcing this also helps
        # catch malicious input.
        body = body.decode('ascii')
        return parse_query_string(body, keep_blank=self._keep_blank, csv=self._csv)
    except Exception as err:
        raise errors.MediaMalformedError('URL-encoded') from err

def __init__(self, initial=None):
    self._resolve = self._create_resolver()

    handlers = initial or {
        MEDIA_JSON: JSONHandler(),
        MEDIA_MULTIPART: MultipartFormHandler(),
        MEDIA_URLENCODED: URLEncodedFormHandler(),
    }

    # NOTE(jmvrbanac): Directly calling UserDict as it's not inheritable.
    # Also, this results in self.update(...) being called.
    UserDict.__init__(self, handlers)

def _create_resolver(self):
    # PERF(kgriffs): Under PyPy the LRU is relatively expensive as compared
    #   to the common case of the self.data lookup succeeding. Using
    #   _lru_cache_for_simple_logic() takes this into account by essentially
    #   creating a nop but also decorating the method with a dummy
    #   cache_clear().
    # PERF(kgriffs): Most apps will probably only use one or two media handlers,
    #   but we use maxsize=64 to give us some wiggle room just in case someone
    #   is using versioned media types or something, and to cover various
    #   combinations of the method args. We may need to tune this later.
    @misc._lru_cache_for_simple_logic(maxsize=64)
    def resolve(media_type, default, raise_not_found=True):
        if media_type == '*/*' or not media_type:
            media_type = default

        # PERF(kgriffs): Under CPython we do not need this shortcut to
        #   improve performance since most calls will be resolved by the
        #   LRU cache on resolve(). On the other hand, it doesn't hurt,
        #   and it certainly makes a difference under PyPy.
        try:
            handler = self.data[media_type]
        except KeyError:
            handler = None

        if not handler:
            # PERF(kgriffs): We just do this slower check every time, rather
            #   than trying to first check the dict directly, since the result
            #   will almost always be cached anyway.
            # NOTE(kgriffs): Wrap keys in a tuple to make them hashable.
            matched_type = _best_match(media_type, tuple(self.data.keys()))

            if not matched_type:
                if raise_not_found:
                    raise errors.HTTPUnsupportedMediaType(
                        description='{0} is an unsupported media type.'.format(
                            media_type
                        )
                    )

                return None, None, None

            handler = self.data[matched_type]

        return (
            handler,
            getattr(handler, '_serialize_sync', None),
            getattr(handler, '_deserialize_sync', None),
        )

    return resolve

def __getitem__(self, key):
    # PERF(vytas): On CPython, using this mapping interface (instead of a
    #   standard dict) to get, set and delete items incurs overhead
    #   approximately comparable to that of two function calls
    #   (per get/set/delete operation, that is).
    return self.__dict__.__getitem__(key)

def __getattr__(name):
    if name == 'json':
        import warnings
        import json  # NOQA
        from .deprecation import DeprecatedWarning

        warnings.warn(
            'Importing json from "falcon.util" is deprecated.', DeprecatedWarning
        )
        return json
    from types import ModuleType

    # fallback to the default implementation
    mod = sys.modules[__name__]
    return ModuleType.__getattr__(mod, name)

def __eq__(self, other):
    if isinstance(other, type(self)):
        return self.__dict__.__eq__(other.__dict__)
    return self.__dict__.__eq__(other)

def __ne__(self, other):
    if isinstance(other, type(self)):
        return self.__dict__.__ne__(other.__dict__)
    return self.__dict__.__ne__(other)

def lower_items(self):
    """Like iteritems(), but with all lowercase keys."""
    return ((lowerkey, keyval[1]) for (lowerkey, keyval) in self._store.items())

def __eq__(self, other):
    if isinstance(other, Mapping):
        other = CaseInsensitiveDict(other)
    else:
        return NotImplemented
    # Compare insensitively
    return dict(self.lower_items()) == dict(other.lower_items())

def pipe(self, destination=None):
    while True:
        chunk = self.read(self._chunk_size)
        if not chunk:
            break

        if destination is not None:
            destination.write(chunk)

def load_app(parser, args):

    try:
        module, instance = args.app_module.split(':', 1)
    except ValueError:
        parser.error(
            'The app_module must include a colon between the module and instance'
        )
    try:
        app = getattr(importlib.import_module(module), instance)
    except AttributeError:
        parser.error('{!r} not found in module {!r}'.format(instance, module))

    if not isinstance(app, falcon.App):
        if callable(app):
            app = app()
            if not isinstance(app, falcon.App):
                parser.error(
                    '{} did not return a falcon.App instance'.format(args.app_module)
                )
        else:
            parser.error(
                'The instance must be of falcon.App or be '
                'a callable without args that returns falcon.App'
            )
    return app

def route_main():
    print(
        'The "falcon-print-routes" command is deprecated. '
        'Please use "falcon-inspect-app"'
    )
    main()

def main():
    parser = make_parser()
    args = parser.parse_args()
    app = load_app(parser, args)
    if args.route_only:
        routes = inspect_routes(app)
        visitor = StringVisitor(args.verbose, args.internal)
        for route in routes:
            print(visitor.process(route))
    else:
        print(inspect_app(app).to_string(args.verbose, args.internal))

